package desktop

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

// ApplyEnvironment overlays operator settings on the private persisted state.
// Passwords and tokens are generated by OpenConfig and have no launcher env
// override: operator configuration and runtime identity stay separate.
func ApplyEnvironment(cfg Config) (Config, error) {
	paths := map[string]*string{
		"LAUNCHER_SERVER": &cfg.Server, "LAUNCHER_PYTHON": &cfg.Python,
		"LAUNCHER_PARSER_DIR": &cfg.ParserDir, "LAUNCHER_POSTGRES_BIN": &cfg.PostgresBin,
		"LAUNCHER_REDIS": &cfg.Redis, "LAUNCHER_WEB_DIR": &cfg.WebDir,
	}
	for key, field := range paths {
		if value := strings.TrimSpace(os.Getenv(key)); value != "" {
			if !filepath.IsAbs(value) {
				return cfg, fmt.Errorf("%s must be an absolute path", key)
			}
			*field = value
		}
	}
	ports := map[string]*int{
		"LAUNCHER_MANAGEMENT_PORT": &cfg.Ports.Manager, "LAUNCHER_HTTP_PORT": &cfg.Ports.API,
		"LAUNCHER_MCP_PORT": &cfg.Ports.MCP, "LAUNCHER_POSTGRES_PORT": &cfg.Ports.Postgres,
		"LAUNCHER_REDIS_PORT": &cfg.Ports.Redis, "LAUNCHER_PARSER_PORT": &cfg.Ports.Parser,
	}
	for key, field := range ports {
		if value := strings.TrimSpace(os.Getenv(key)); value != "" {
			port, err := strconv.Atoi(value)
			if err != nil || port < 1 || port > 65535 {
				return cfg, fmt.Errorf("%s must be a port between 1 and 65535", key)
			}
			*field = port
		}
	}
	for key, field := range map[string]*time.Duration{
		"LAUNCHER_STARTUP_TIMEOUT": &cfg.StartupTimeout, "LAUNCHER_STOP_TIMEOUT": &cfg.StopTimeout,
	} {
		if value := strings.TrimSpace(os.Getenv(key)); value != "" {
			duration, err := time.ParseDuration(value)
			if err != nil || duration < time.Second {
				return cfg, fmt.Errorf("%s must be a duration of at least 1s", key)
			}
			*field = duration
		}
	}
	if value := strings.TrimSpace(os.Getenv("LAUNCHER_EXTRACTION_ENGINE")); value != "" {
		cfg.ExtractionEngine = value
	}
	return cfg, cfg.Validate()
}
